  `factory_id` bigint NOT NULL COMMENT '工厂ID(关联qxx_md_factory)',
  `unit_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '单位编码(如PCS/ROLL/KG/TON/M/G)',
