--
-- Table structure for table `qxx_pro_exception`
--

DROP TABLE IF EXISTS `qxx_pro_exception`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `qxx_pro_exception` (
  `exception_id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `factory_id` bigint NOT NULL COMMENT '工厂ID',
  `exception_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '异常单号(EX20260902-014)',
  `exception_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '异常类型 QUALITY质量数量/MATERIAL缺料/DELAY进度延迟/RETURN客户退货',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'OPEN' COMMENT '状态 OPEN待处理/PROCESSING处理中/CLOSED已关闭/VOID已作废',
  `responsible_party` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING' COMMENT '责任方 FACTORY本厂/SUPPLIER供应商/CUSTOMER客户/PENDING待定',
  `workorder_id` bigint DEFAULT NULL COMMENT '工单ID',
  `workorder_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工单编码快照',
  `workorder_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工单名称快照',
  `task_id` bigint DEFAULT NULL COMMENT '工序任务ID',
  `task_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '任务编号快照',
  `process_id` bigint DEFAULT NULL COMMENT '工序ID',
  `process_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工序编码快照',
  `process_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工序名称快照',
  `target_type` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'TASK' COMMENT '关联对象类型(预留:二期挂销售订单)',
  `target_id` bigint DEFAULT NULL COMMENT '关联对象ID',
  `target_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联对象编号',
  `reporter_id` bigint DEFAULT NULL COMMENT '上报人用户ID',
  `reporter_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '上报人账号快照',
  `occur_time` datetime DEFAULT NULL COMMENT '异常发生时间',
  `impact_quantity` decimal(14,2) DEFAULT NULL COMMENT '影响数量',
  `description` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '异常情况说明',
  `scene_images` varchar(2000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '现场照片(MinIO URL逗号串,最多9张)',
  `quality_subclass` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '质量小类 BROKEN做坏了/SHORT做少了',
  `usable_quantity` decimal(14,2) DEFAULT NULL COMMENT '可使用数量',
  `need_rework` char(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否需要返工 Y/N',
  `item_id` bigint DEFAULT NULL COMMENT '缺料物料ID',
  `item_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '缺料物料编码',
  `item_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '缺料物料名称',
  `shortage_quantity` decimal(14,2) DEFAULT NULL COMMENT '缺料数量',
  `expected_arrival_date` date DEFAULT NULL COMMENT '预计到货日期',
  `original_plan_time` datetime DEFAULT NULL COMMENT '原计划完成时间',
  `new_expected_time` datetime DEFAULT NULL COMMENT '新预计完成时间',
  `delay_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '延迟原因',
  `return_quantity` decimal(14,2) DEFAULT NULL COMMENT '退货数量',
  `return_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '退货原因',
  `customer_accept_rework` char(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户是否接受返工 Y/N',
  `conclusion` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '处理结论',
  `resolve_type` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '出口动作 REWORK返工/REMAKE补做/PURCHASE补料采购/RESCHEDULE顺延/SCRAP报废/CONCESSION让步接收/REFUND退款结单',
  `resolve_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '选出口处理人',
  `resolve_time` datetime DEFAULT NULL COMMENT '选出口时间',
  `target_doc_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '处理产生单据类型 TASK/PUR_ORDER',
  `target_doc_id` bigint DEFAULT NULL COMMENT '处理产生单据ID',
  `target_doc_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '处理产生单据编号',
  `scrap_quantity` decimal(14,2) DEFAULT NULL COMMENT '报废数量',
  `close_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关闭人',
  `close_time` datetime DEFAULT NULL COMMENT '关闭时间',
  `create_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`exception_id`),
  UNIQUE KEY `uk_factory_code` (`factory_id`,`exception_code`),
  KEY `idx_wo_status` (`workorder_id`,`status`),
  KEY `idx_task` (`task_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='生产异常单';
/*!40101 SET character_set_client = @saved_cs_client */;

