--
-- Table structure for table `qxx_pur_order`
--

DROP TABLE IF EXISTS `qxx_pur_order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `qxx_pur_order` (
  `order_id` bigint NOT NULL AUTO_INCREMENT COMMENT '采购订单ID',
  `factory_id` bigint NOT NULL COMMENT '工厂ID(关联qxx_md_factory)',
  `order_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '采购订单编码(唯一)',
  `order_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '采购订单名称',
  `vendor_id` bigint NOT NULL COMMENT '供应商ID(关联qxx_md_vendor,vendor_type=MATERIAL)',
  `vendor_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '供应商编码',
  `vendor_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '供应商名称',
  `purchase_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'PAPER' COMMENT '采购类型:PAPER-纸张,AUX-辅料(绳子/胶水/油墨),PACK-包材(纸箱),OTHER-其他',
  `order_date` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '下单日期',
  `expected_date` datetime DEFAULT NULL COMMENT '预计到货日期',
  `purchaser` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '采购员(申购人)',
  `approver` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批人',
  `total_quantity` decimal(14,4) DEFAULT '0.0000' COMMENT '原订购总数量(冻结值,取消/关闭不改;已取消数见查询计算列)',
  `total_amount` decimal(14,2) DEFAULT '0.00' COMMENT '原采购总金额(冻结值,取消/关闭不改;已收/已取消金额见查询计算列)',
  `currency` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'CNY' COMMENT '币种:CNY-人民币,USD-美元',
  `source_order_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联客户订单号(如PO#ORD66003MT)',
  `status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'DRAFT' COMMENT '状态:DRAFT-草稿,APPROVED-已审批,ORDERED-已下单,RECEIVING-收货中,RECEIVED-已收货,CLOSED-已关闭,CANCEL-已取消',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '备注',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `workorder_id` bigint DEFAULT NULL COMMENT '关联工单ID',
  `workorder_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联工单编码',
  `cancel_reason` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '取消原因',
  `cancel_time` datetime DEFAULT NULL COMMENT '取消时间',
  `cancel_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '取消人',
  `close_reason` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关闭原因(强制关闭时填写)',
  `close_time` datetime DEFAULT NULL COMMENT '关闭时间',
  `close_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关闭人',
  PRIMARY KEY (`order_id`),
  UNIQUE KEY `uk_order_code` (`order_code`),
  KEY `idx_factory_id` (`factory_id`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='采购订单头表';
/*!40101 SET character_set_client = @saved_cs_client */;

