CREATE TABLE `qxx_qc_ipqc` (
  `ipqc_id` bigint NOT NULL AUTO_INCREMENT COMMENT '过程检验单ID',
  `factory_id` bigint NOT NULL COMMENT '工厂ID',
  `ipqc_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '检验单编码',
  `ipqc_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检验单名称',
  `ipqc_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'FIRST_CHECK/TOUR_CHECK/LAST_CHECK/SPOT_CHECK',
  `template_id` bigint NOT NULL COMMENT '模板ID',
  `source_doc_id` bigint DEFAULT NULL COMMENT '来源单据ID(pro_card_process.record_id 或 qxx_wm_product_recpt.recpt_id)',
  `source_doc_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源类型:pro_card_process/wm_product_recpt',
  `source_doc_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源单据编码',
  `source_line_id` bigint DEFAULT NULL COMMENT '来源行ID',
  `workorder_id` bigint DEFAULT NULL COMMENT '工单ID',
  `workorder_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工单编码',
  `workorder_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工单名称',
  `card_id` bigint DEFAULT NULL COMMENT '流转卡ID',
  `card_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '流转卡编码',
  `task_id` bigint DEFAULT NULL COMMENT '任务ID',
