--
-- Table structure for table `qxx_qc_order_line`
--

DROP TABLE IF EXISTS `qxx_qc_order_line`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `qxx_qc_order_line` (
  `line_id` bigint NOT NULL AUTO_INCREMENT COMMENT '行ID',
  `factory_id` bigint NOT NULL COMMENT '工厂ID',
  `qc_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '检验单类型:IQC/IPQC/OQC/RQC',
  `qc_id` bigint NOT NULL COMMENT '检验单ID(多态)',
  `index_id` bigint NOT NULL COMMENT '检测项ID',
  `index_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检测项编码',
  `index_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检测项名称',
  `index_type` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检测项类型',
  `qc_tool` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检测工具',
  `qc_result_type` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '值类型',
  `check_method` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检测方法',
  `stander_val` double(12,4) DEFAULT NULL COMMENT '标准值(快照)',
  `unit_of_measure` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '单位',
  `threshold_min` double(12,4) DEFAULT NULL COMMENT '允许下偏差(快照)',
  `threshold_max` double(12,4) DEFAULT NULL COMMENT '允许上偏差(快照)',
  `check_val_text` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '实测值(数值型存数字文本/文本型存内容/字典型存dict_value)',
  `cr_quantity` int DEFAULT '0' COMMENT '致命缺陷数(该检测项)',
  `maj_quantity` int DEFAULT '0' COMMENT '严重缺陷数',
  `min_quantity` int DEFAULT '0' COMMENT '轻微缺陷数',
  `line_result` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '行结果:PASS/FAIL',
  `order_num` int DEFAULT '1' COMMENT '排序',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '备注',
  `create_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`line_id`),
  KEY `idx_factory_id` (`factory_id`),
  KEY `idx_qc_order` (`qc_type`,`qc_id`)
) ENGINE=InnoDB AUTO_INCREMENT=258 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='检验单行(四类共用)';
/*!40101 SET character_set_client = @saved_cs_client */;

