--
-- Table structure for table `qxx_qc_rqc`
--

DROP TABLE IF EXISTS `qxx_qc_rqc`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `qxx_qc_rqc` (
  `rqc_id` bigint NOT NULL AUTO_INCREMENT COMMENT '退料检验单ID',
  `factory_id` bigint NOT NULL COMMENT '工厂ID',
  `rqc_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '检验单编码',
  `rqc_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检验单名称',
  `rqc_type` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'PROD_RETURN' COMMENT 'PROD_RETURN/PURCHASE_RETURN/QC_REJECT',
  `template_id` bigint NOT NULL COMMENT '模板ID',
  `source_doc_id` bigint DEFAULT NULL COMMENT '来源单据ID(qxx_wm_rt_issue.rt_id)',
  `source_doc_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'wm_rt_issue' COMMENT '来源类型',
  `source_doc_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源单据编码',
  `source_line_id` bigint DEFAULT NULL COMMENT '来源行ID',
  `workorder_id` bigint DEFAULT NULL COMMENT '工单ID(生产退料)',
  `workorder_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工单编码',
  `vendor_id` bigint DEFAULT NULL COMMENT '供应商ID(采购退货)',
  `vendor_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '供应商编码',
  `vendor_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '供应商名称',
  `item_id` bigint NOT NULL COMMENT '物料ID',
  `item_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '物料编码',
  `item_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '物料名称',
  `specification` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '规格型号',
  `unit_of_measure` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '单位',
  `batch_code` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '批次号',
  `quantity_check` double(12,4) DEFAULT NULL COMMENT '实际检测数量',
  `quantity_min_check` int DEFAULT '1' COMMENT '抽检样本量(模板快照)',
  `quantity_max_unqualified` int DEFAULT '0' COMMENT 'Ac值(模板快照)',
  `quantity_qualified` double(12,4) DEFAULT '0.0000' COMMENT '合格数',
  `quantity_unqualified` double(12,4) DEFAULT '0.0000' COMMENT '不合格数',
  `cr_rate_limit` double(12,2) DEFAULT '0.00' COMMENT '致命缺陷率阈值(模板快照,%)',
  `maj_rate_limit` double(12,2) DEFAULT '0.00' COMMENT '严重缺陷率阈值(模板快照,%)',
  `min_rate_limit` double(12,2) DEFAULT '0.00' COMMENT '轻微缺陷率阈值(模板快照,%)',
  `cr_quantity` int DEFAULT '0' COMMENT '致命缺陷数',
  `maj_quantity` int DEFAULT '0' COMMENT '严重缺陷数',
  `min_quantity` int DEFAULT '0' COMMENT '轻微缺陷数',
  `cr_rate` double(12,2) DEFAULT '0.00' COMMENT '致命缺陷率(%)',
  `maj_rate` double(12,2) DEFAULT '0.00' COMMENT '严重缺陷率(%)',
  `min_rate` double(12,2) DEFAULT '0.00' COMMENT '轻微缺陷率(%)',
  `check_result` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'PASS/FAIL/CONCESSION',
  `concession_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '让步理由',
  `return_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '退料原因',
  `responsibility` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '责任归属:SUPPLIER/PRODUCTION/STORAGE/OTHER',
  `inspect_date` datetime DEFAULT NULL COMMENT '检验日期',
  `inspector` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检验员',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'PENDING' COMMENT 'PENDING/INSPECTING/COMPLETED/CLOSED',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '备注',
  `create_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`rqc_id`),
  UNIQUE KEY `uk_factory_rqc_code` (`factory_id`,`rqc_code`),
  KEY `idx_factory_id` (`factory_id`),
  KEY `idx_source` (`source_doc_type`,`source_doc_id`),
  KEY `idx_item` (`item_id`)
) ENGINE=InnoDB AUTO_INCREMENT=100 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='退料检验单';
/*!40101 SET character_set_client = @saved_cs_client */;

