DROP TABLE IF EXISTS `qxx_qc_template_index`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `qxx_qc_template_index` (
  `record_id` bigint NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `factory_id` bigint NOT NULL COMMENT '工厂ID',
  `template_id` bigint NOT NULL COMMENT '模板ID',
  `index_id` bigint NOT NULL COMMENT '检测项ID',
  `index_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '检测项编码',
  `index_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '检测项名称',
  `index_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '检测项类型',
  `qc_tool` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检测工具',
  `qc_result_type` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '值类型',
  `check_method` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检测方法/要求',
  `stander_val` double(12,4) DEFAULT NULL COMMENT '标准值(数值型)',
  `unit_of_measure` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '单位',
  `threshold_min` double(12,4) DEFAULT NULL COMMENT '允许下偏差(实测<标准+下偏差=不合格)',
  `threshold_max` double(12,4) DEFAULT NULL COMMENT '允许上偏差(实测>标准+上偏差=不合格)',
  `order_num` int DEFAULT '1' COMMENT '排序',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '备注',
  `create_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`record_id`),
  KEY `idx_factory_id` (`factory_id`),
  KEY `idx_template` (`template_id`)
) ENGINE=InnoDB AUTO_INCREMENT=164 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='模板-检测项表';
