DROP TABLE IF EXISTS `qxx_sal_order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `qxx_sal_order` (
  `order_id` bigint NOT NULL AUTO_INCREMENT COMMENT '销售订单ID',
  `factory_id` bigint NOT NULL COMMENT '工厂ID(关联qxx_md_factory)',
  `order_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '销售订单号(SO+yyyyMMdd+流水,genSerialCode ORDER_NO)',
  `order_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '订单名称',
  `order_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'STANDARD' COMMENT '订单类型 STANDARD/SMALL_BATCH/GIFT/STOCK/PLATE',
  `client_id` bigint DEFAULT NULL COMMENT '客户ID(关联qxx_md_client)',
  `client_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户编码',
  `client_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户名称',
  `client_nick` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户简称',
  `client_order_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户订单号(PO号)',
  `salesperson` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务员',
  `business_line` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务线:DOMESTIC-内贸,FOREIGN-外贸,SPOT-现货',
  `sample_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT 'N' COMMENT '是否有样品(Y-是,N-否)',
  `outsource_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT 'N' COMMENT '是否外发 Y/N',
  `package_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT 'N' COMMENT '是否包装 Y/N',
  `source` tinyint(1) NOT NULL DEFAULT '1' COMMENT '订单来源:1-直接新增,2-CRM系统',
  `order_date` datetime DEFAULT NULL COMMENT '订单日期',
  `request_date` datetime DEFAULT NULL COMMENT '需求交期(客户要求交货日)',
  `total_amount` decimal(14,2) DEFAULT NULL COMMENT '订单总金额',
  `payment_method` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '付款方式',
  `status` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'PENDING_ACCEPT' COMMENT '订单状态：PENDING_ACCEPT待接单/CONFIRMED已确认/PRODUCING生产中/SHIPPED已出货/CLOSED已结单/CANCEL已取消',
  `approve_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审核人',
  `approve_time` datetime DEFAULT NULL COMMENT '审核时间',
  `approve_remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审核意见/驳回原因',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '备注',
  `create_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`order_id`),
  UNIQUE KEY `uk_order_code` (`order_code`),
  KEY `idx_factory_id` (`factory_id`)
) ENGINE=InnoDB AUTO_INCREMENT=230 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='销售订单表';
/*!40101 SET character_set_client = @saved_cs_client */;

