--
-- Table structure for table `qxx_sal_order_line`
--

DROP TABLE IF EXISTS `qxx_sal_order_line`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `qxx_sal_order_line` (
  `line_id` bigint NOT NULL AUTO_INCREMENT COMMENT '明细行ID',
  `factory_id` bigint NOT NULL COMMENT '工厂ID(关联qxx_md_factory)',
  `order_id` bigint NOT NULL COMMENT '销售订单ID(关联qxx_sal_order)',
  `line_no` int DEFAULT NULL COMMENT '行号',
  `product_id` bigint DEFAULT NULL COMMENT '产品ID(关联qxx_md_item,引用既有SPU/SKU)',
  `product_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品编码',
  `product_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品名称',
  `product_spc` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品规格型号',
  `unit_of_measure` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '主单位编码',
  `unit_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '主单位名称',
  `quantity` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '订单数量',
  `unit_price` decimal(14,4) DEFAULT NULL COMMENT '单价',
  `line_amount` decimal(14,2) DEFAULT NULL COMMENT '行金额(单价*数量)',
  `spacing` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '间距(纸袋专用,如7.5cm)',
  `product_size` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品尺寸(长*宽*高mm)',
  `printing_req` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '印刷要求',
  `rope_spec` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '绳料规格(纸袋专用,如红色圆纸绳)',
  `package_req` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '包装要求',
  `shipping_req` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发货要求',
  `route_product_id` bigint DEFAULT NULL COMMENT '产品-路线绑定ID qxx_pro_route_product.record_id',
  `route_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '路线编码快照',
  `route_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '路线名称快照',
  `request_date` datetime DEFAULT NULL COMMENT '行级需求交期',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '备注',
  `create_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `line_attrs` json DEFAULT NULL COMMENT '扩展属性(JSON扁平结构),分类驱动的动态属性快照',
  PRIMARY KEY (`line_id`),
  KEY `idx_factory_id` (`factory_id`),
  KEY `idx_order_id` (`order_id`)
) ENGINE=InnoDB AUTO_INCREMENT=227 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='销售订单明细行表';
