--
-- Table structure for table `qxx_sys_ai_chat_session`
--

DROP TABLE IF EXISTS `qxx_sys_ai_chat_session`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `qxx_sys_ai_chat_session` (
  `session_id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `factory_id` bigint NOT NULL COMMENT '工厂ID',
