  `oqc_id` bigint DEFAULT NULL COMMENT '出货检验单ID(关联qxx_qc_oqc)',
  `oqc_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '出货检验单编码',
