  `sales_order_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '销售订单编码',
  `status` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'DRAFT' COMMENT '状态:DRAFT-草稿,CONFIRMED-已确认,POSTED-已过账,SHIPPED-已发货',
