DROP TABLE IF EXISTS `qxx_wm_product_sales_shipment`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `qxx_wm_product_sales_shipment` (
  `shipment_id` bigint NOT NULL AUTO_INCREMENT COMMENT '发运单ID',
  `factory_id` bigint NOT NULL COMMENT '工厂ID(关联qxx_md_factory)',
  `sales_id` bigint NOT NULL COMMENT '销售出库单ID(关联qxx_wm_product_sales)',
  `shipment_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发运单号(编码规则SHIP_NO)',
  `ship_method` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'LOGISTICS' COMMENT '发货方式:LOGISTICS-物流,EXPRESS-快递,PICKUP-自提,SELF-客户自送',
  `logistics_company` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '物流/承运商公司',
  `tracking_no` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '运单号',
  `logistics_fee` decimal(12,2) DEFAULT '0.00' COMMENT '物流费用',
  `vehicle_no` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '车牌号(自提/物流)',
  `driver_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '司机姓名',
  `driver_tel` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '司机电话',
  `receiver_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '实际收货人',
  `receiver_tel` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '收货人电话',
  `shipping_address` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '收货详细地址',
  `plan_ship_date` date DEFAULT NULL COMMENT '计划发货日期',
  `actual_ship_date` datetime DEFAULT NULL COMMENT '实际发货时间',
  `shipped_quantity` decimal(16,4) DEFAULT '0.0000' COMMENT '本次发运数量(冗余,便于统计)',
  `box_count` int DEFAULT '0' COMMENT '本次发运箱数',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'IN_TRANSIT' COMMENT '发运单状态：IN_TRANSIT-在途,RECEIVED-已签收,CANCELED-已取消',
  `received_time` datetime DEFAULT NULL COMMENT '签收时间',
  `received_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '签收人',
  `received_remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '签收备注',
  `attachment_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '回单附件URL(MinIO,逗号分隔多文件)',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '备注',
  `create_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`shipment_id`),
  UNIQUE KEY `uk_shipment_code` (`factory_id`,`shipment_code`),
  UNIQUE KEY `uk_factory_shipment_code` (`factory_id`,`shipment_code`),
  KEY `idx_factory_id` (`factory_id`),
  KEY `idx_sales_id` (`sales_id`)
) ENGINE=InnoDB AUTO_INCREMENT=204 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='销售出库-发运单(支持多次发运)';
