INSERT INTO `sys_config` VALUES (1,'主框架页-默认皮肤样式名称','sys.index.skinName','skin-blue','Y','admin','2026-07-02 12:15:47','',NULL,'蓝色 skin-blue、绿色 skin-green、紫色 skin-purple、红色 skin-red、黄色 skin-yellow'),(2,'用户管理-账号初始密码','sys.user.initPassword','123456','Y','admin','2026-07-02 12:15:47','',NULL,'初始化密码 123456'),(3,'主框架页-侧边栏主题','sys.index.sideTheme','theme-dark','Y','admin','2026-07-02 12:15:47','',NULL,'深色主题theme-dark，浅色主题theme-light'),(4,'账号自助-验证码开关','sys.account.captchaEnabled','false','N','admin','2026-07-02 12:15:47','admin','2026-07-08 17:46:37','是否开启验证码功能（true开启，false关闭）'),(5,'账号自助-是否开启用户注册功能','sys.account.registerUser','false','Y','admin','2026-07-02 12:15:47','',NULL,'是否开启注册用户功能（true开启，false关闭）'),(6,'用户登录-黑名单列表','sys.login.blackIPList','','Y','admin','2026-07-02 12:15:47','',NULL,'设置登录IP黑名单限制，多个匹配项以;分隔，支持匹配（*通配、网段）'),(7,'用户管理-初始密码修改策略','sys.account.initPasswordModify','1','Y','admin','2026-07-02 12:15:47','',NULL,'0：初始密码修改策略关闭，没有任何提示，1：提醒用户，如果未修改初始密码，则在登录时就会提醒修改密码对话框'),(8,'用户管理-账号密码更新周期','sys.account.passwordValidateDays','0','Y','admin','2026-07-02 12:15:47','',NULL,'密码更新周期（填写数字，数据初始化值为0不限制，若修改必须为大于0小于365的正整数），如果超过这个周期登录系统时，则在登录时就会提醒修改密码对话框'),(9,'用户管理-密码字符范围','sys.account.chrtype','0','Y','admin','2026-07-02 12:15:47','',NULL,'默认任意字符范围，0任意（密码可以输入任意字符），1数字（密码只能为0-9数字），2英文字母（密码只能为a-z和A-Z字母），3字母和数字（密码必须包含字母，数字）,4字母数字和特殊字符（目前支持的特殊字符包括：~!@#$%^&*()-=_+）'),(100,'进度临期阈值(小时)','mes.progress.warnHours','24','Y','admin','2026-08-25 14:12:58','',NULL,'任务计划结束前N小时未完成判临期'),(101,'工单临期阈值(天)','mes.progress.warnDays','2','Y','admin','2026-08-25 14:12:58','',NULL,'工单交期前N天未完工判临期'),(102,'进度滞后容差(百分点)','mes.progress.behindTolerance','10','Y','admin','2026-08-25 14:12:58','',NULL,'产出进度比时间进度低超N个点判滞后'),(103,'班组快照开关','mes.progress.snapshotTeam','true','Y','admin','2026-08-25 14:12:58','',NULL,'报工/上下工是否快照班组'),(104,'自动排产开关','mes.pro.schedule.autoEnabled','true','Y','admin','2026-09-09 10:18:49','admin','2026-09-18 16:50:13','甘特图自动排产开关：false 停用(默认)——隐藏自动排产按钮、后端不再自动排产，需在甘特图手工新增任务/指派机台；true 启用自动排产'),(105,'AI助手-接口地址','mes.ai.baseUrl','https://api.deepseek.com','N','admin','2026-10-16 22:58:41','',NULL,'OpenAI 兼容 /chat/completions 服务地址'),(106,'AI助手-API密钥','mes.ai.apiKey','sk-a68e09e24231431988483ae0afc3ff25','N','admin','2026-10-16 22:58:41','',NULL,'DeepSeek API Key（sk-...），为空时 AI 助手不可用'),(107,'AI助手-模型','mes.ai.model','deepseek-chat','N','admin','2026-10-16 22:58:41','',NULL,'对话模型名');
